    Bug 1942554 - Better prioritise closing of idle message databases. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D234915

diff --git a/mailnews/base/src/MsgDBCacheManager.sys.mjs b/mailnews/base/src/MsgDBCacheManager.sys.mjs
index c8f59544db6..415c9f26a31 100644
--- a/mailnews/base/src/MsgDBCacheManager.sys.mjs
+++ b/mailnews/base/src/MsgDBCacheManager.sys.mjs
@@ -108,6 +108,7 @@ export var msgDBCacheManager = {
    * Checks if any DBs need to be closed due to inactivity or too many of them open.
    */
   checkCachedDBs() {
+    const keepOpenSize = Services.prefs.getIntPref("mail.db.keep_open_size");
     const idleLimit = Services.prefs.getIntPref("mail.db.idle_limit");
     const maxOpenDBs = Services.prefs.getIntPref("mail.db.max_open");

@@ -139,8 +140,8 @@ export var msgDBCacheManager = {
         continue;
       }

-      if (db.lastUseTime < closeThreshold) {
-        // DB open too log without activity.
+      if (db.lastUseTime < closeThreshold && db.databaseSize < keepOpenSize) {
+        // DB open too long without activity.
         log.debug("Closing expired DB for folder: " + db.folder.name);
         db.folder.msgDatabase = null;
         numClosing++;
@@ -168,8 +169,14 @@ export var msgDBCacheManager = {
       // so if there are so many windows open, it may be possible for
       // more than maxOpenDBs folders to stay open after this loop.
       log.info("Need to close " + dbsToClose + " more DBs");
-      // Order databases by lowest lastUseTime (oldest) at the end.
-      dbs.sort((a, b) => b.lastUseTime - a.lastUseTime);
+      // Order databases by size (smallest) and lowest lastUseTime (oldest)
+      // at the end. In practice this is dominated by the size, but not
+      // completely.
+      dbs.sort(
+        (a, b) =>
+          Math.log10(b.databaseSize) * b.lastUseTime -
+          Math.log10(a.databaseSize) * a.lastUseTime
+      );
       while (dbsToClose > 0) {
         const db = dbs.pop();
         log.debug("Closing DB for folder: " + db.folder.name);
diff --git a/mailnews/mailnews.js b/mailnews/mailnews.js
index 8c095256c60..3157e78783a 100644
--- a/mailnews/mailnews.js
+++ b/mailnews/mailnews.js
@@ -135,9 +135,12 @@ pref("mailnews.headers.showSender", false);
 // be greater than one hour so daylight savings time changes don't affect us.
 // We will still always regenerate .msf files if the file size changes.
 pref("mail.db_timestamp_leeway", 4000);
-// How long should we leave idle db's open, in milliseconds.
+// MsgDBCacheManager will close databases that have been idle for idle_limit
+// milliseconds and are smaller than keep_open_size bytes.
 pref("mail.db.idle_limit", 300000);
-// How many db's should we leave open? LRU db's will be closed first
+pref("mail.db.keep_open_size", 1048576);
+// How many db's should we leave open? MsgDBCacheManager will close the
+// smallest and least-recently-used first.
 pref("mail.db.max_open", 30);

 // Should we allow folders over 4GB in size?
